import{_ as p,a0 as o,w as r,s as d,I as a,x as e,a1 as n,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何使用 Apache Web 服务器配置多个站点 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Apache Web 服务器配置多个站点 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Apache Web 服务器配置多个站点 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Apache Web 服务器配置多个站点 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180329 How to configure multiple websites with Apache web server","title":"如何使用 Apache Web 服务器配置多个站点","tag":"201810","desc":""},"relativePath":"201810/20180329 How to configure multiple websites with Apache web server.md","filePath":"[post].md"}'),h={name:"201810/20180329 How to configure multiple websites with Apache web server.md"};function c(g,s,b,u,k,m){const t=o("Link");return r(),d("div",null,[s[21]||(s[21]=a("h1",{id:"如何使用-apache-web-服务器配置多个站点",tabindex:"-1"},[e("如何使用 Apache Web 服务器配置多个站点 "),a("a",{class:"header-anchor",href:"#如何使用-apache-web-服务器配置多个站点","aria-label":"Permalink to “如何使用 Apache Web 服务器配置多个站点”"},"​")],-1)),s[22]||(s[22]=a("blockquote",null,[a("p",null,"如何在流行而强大的 Apache Web 服务器上托管两个或多个站点。")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/apache-feathers.jpg?itok=fnrpsu3G",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在我的",-1)),n(t,{href:"https://linux.cn/article-9506-1.html"},{default:i(()=>[...s[0]||(s[0]=[e("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=e("中，我解释了如何为单个站点配置 Apache Web 服务器，事实证明这很容易。在这篇文章中，我将向你展示如何使用单个 Apache 实例来服务多个站点。",-1))]),s[24]||(s[24]=l('<p>注意：我写这篇文章的环境是 Fedora 27 虚拟机，配置了 Apache 2.4.29。如果你用另一个发行版或不同的 Fedora 版本，那么你使用的命令以及配置文件的位置和内容可能会有所不同。</p><p>正如我之前的文章中提到的，Apache 的所有配置文件都位于 <code>/etc/httpd/conf</code> 和 <code>/etc/httpd/conf.d</code>。默认情况下，站点的数据位于 <code>/var/www</code> 中。对于多个站点，你需要提供多个位置，每个位置对应托管的站点。</p><h3 id="基于名称的虚拟主机" tabindex="-1">基于名称的虚拟主机 <a class="header-anchor" href="#基于名称的虚拟主机" aria-label="Permalink to “基于名称的虚拟主机”">​</a></h3><p>使用基于名称的虚拟主机，你可以为多个站点使用一个 IP 地址。现代 Web 服务器，包括 Apache，使用指定 URL 的 <code>hostname</code> 部分来确定哪个虚拟 Web 主机响应页面请求。这仅仅需要比一个站点更多的配置。</p><p>即使你只从单个站点开始，我也建议你将其设置为虚拟主机，这样可以在以后更轻松地添加更多站点。在本文中，我将从上一篇文章中我们停止的地方开始，因此你需要设置原来的站点，即基于名称的虚拟站点。</p><h3 id="准备原来的站点" tabindex="-1">准备原来的站点 <a class="header-anchor" href="#准备原来的站点" aria-label="Permalink to “准备原来的站点”">​</a></h3>',6)),a("p",null,[s[4]||(s[4]=e("在设置第二个站点之前，你需要为现有网站提供基于名称的虚拟主机。如果你现在没有站点，",-1)),n(t,{href:"https://linux.cn/article-9506-1.html"},{default:i(()=>[...s[3]||(s[3]=[e("请返回并立即创建一个",-1)])]),_:1}),s[5]||(s[5]=e("。",-1))]),s[25]||(s[25]=l(`<p>一旦你有了站点，将以下内容添加到 <code>/etc/httpd/conf/httpd.conf</code> 配置文件的底部（添加此内容是你需要对 <code>httpd.conf</code> 文件进行的唯一更改）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;VirtualHost 127.0.0.1:80&gt;</span></span>
<span class="line"><span>    DocumentRoot /var/www/html</span></span>
<span class="line"><span>    ServerName www.site1.org</span></span>
<span class="line"><span>&lt;/VirtualHost&gt;</span></span></code></pre></div><p>这将是第一个虚拟主机配置节，它应该保持为第一个，以使其成为默认定义。这意味着通过 IP 地址或解析为此 IP 地址但没有特定命名主机配置节的其它名称对服务器的 HTTP 访问将定向到此虚拟主机。所有其它虚拟主机配置节都应跟在此节之后。</p><p>你还需要使用 <code>/etc/hosts</code> 中的条目设置你的网站以提供名称解析。上次，我们只使用了 <code>localhost</code> 的 IP 地址。通常，这可以使用你使用的任何名称服务来完成，例如 Google 或 Godaddy。对于你的测试网站，通过在 <code>/etc/hosts</code> 中的 <code>localhost</code> 行添加一个新名称来完成此操作。添加两个网站的条目，方便你以后不需再次编辑此文件。结果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>127.0.0.1 localhost localhost.localdomain localhost4 localhost4.localdomain4 www.site1.org www.site2.org</span></span></code></pre></div><p>让我们将 <code>/var/www/html/index.html</code> 文件改变得更加明显一点。它应该看起来像这样（带有一些额外的文本来识别这是站点 1）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;h1&gt;Hello World&lt;/h1&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Web site 1.</span></span></code></pre></div><p>重新启动 HTTPD 服务器，已启用对 <code>httpd</code> 配置的更改。然后，你可以从命令行使用 Lynx 文本模式查看网站。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testvm1 ~]# systemctl restart httpd</span></span>
<span class="line"><span>[root@testvm1 ~]# lynx www.site1.org</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                                              Hello World </span></span>
<span class="line"><span>  Web site 1.</span></span>
<span class="line"><span>&lt;snip&gt;</span></span>
<span class="line"><span>Commands: Use arrow keys to move, &#39;?&#39; for help, &#39;q&#39; to quit, &#39;&lt;-&#39; to go back.</span></span>
<span class="line"><span>Arrow keys: Up and Down to move.  Right to follow a link; Left to go back.</span></span>
<span class="line"><span>H)elp O)ptions P)rint G)o M)ain screen Q)uit /=search [delete]=history list</span></span></code></pre></div><p>你可以看到原始网站的修改内容，没有明显的错误，先按下 <code>Q</code> 键，然后按 <code>Y</code> 退出 Lynx Web 浏览器。</p><h3 id="配置第二个站点" tabindex="-1">配置第二个站点 <a class="header-anchor" href="#配置第二个站点" aria-label="Permalink to “配置第二个站点”">​</a></h3><p>现在你已经准备好建立第二个网站。使用以下命令创建新的网站目录结构：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testvm1 html]# mkdir -p /var/www/html2</span></span></code></pre></div><p>注意，第二个站点只是第二个 <code>html</code> 目录，与第一个站点位于同一 <code>/var/www</code> 目录下。</p><p>现在创建一个新的索引文件 <code>/var/www/html2/index.html</code>，其中包含以下内容（此索引文件稍有不同，以区别于原来的网站）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;h1&gt;Hello World -- Again&lt;/h1&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Web site 2.</span></span></code></pre></div><p>在 <code>httpd.conf</code> 中为第二个站点创建一个新的配置节，并将其放在上一个虚拟主机配置节下面（这两个应该看起来非常相似）。此节告诉 Web 服务器在哪里可以找到第二个站点的 HTML 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;VirtualHost 127.0.0.1:80&gt;</span></span>
<span class="line"><span>    DocumentRoot /var/www/html2</span></span>
<span class="line"><span>    ServerName www.site2.org</span></span>
<span class="line"><span>&lt;/VirtualHost&gt;</span></span></code></pre></div><p>重启 HTTPD，并使用 Lynx 来查看结果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@testvm1 httpd]# systemctl restart httpd</span></span>
<span class="line"><span>[root@testvm1 httpd]# lynx www.site2.org</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                                    Hello World -- Again</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Web site 2.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;snip&gt;</span></span>
<span class="line"><span>Commands: Use arrow keys to move, &#39;?&#39; for help, &#39;q&#39; to quit, &#39;&lt;-&#39; to go back.</span></span>
<span class="line"><span>Arrow keys: Up and Down to move.  Right to follow a link; Left to go back.</span></span>
<span class="line"><span>H)elp O)ptions P)rint G)o M)ain screen Q)uit /=search [delete]=history list</span></span></code></pre></div><p>在这里，我压缩了输出结果以适应这个空间。页面的差异表明这是第二个站点。要同时显示两个站点，请打开另一个终端会话并使用 Lynx Web 浏览器查看另一个站点。</p><h3 id="其他考虑" tabindex="-1">其他考虑 <a class="header-anchor" href="#其他考虑" aria-label="Permalink to “其他考虑”">​</a></h3><p>这个简单的例子展示了如何使用 Apache HTTPD 服务器的单个实例来服务于两个站点。当考虑其他因素时，配置虚拟主机会变得有点复杂。</p><p>例如，你可能希望为这些网站中的一个或全部使用一些 CGI 脚本。为此，你可能为 CGI 程序在 <code>/var/www</code> 目录下创建一些目录：<code>/var/www/cgi-bin</code> 和 <code>/var/www/cgi-bin2</code>，以与 HTML 目录命名一致。然后，你需要将配置指令添加到虚拟主机节，以指定 CGI 脚本的目录位置。每个站点可以有下载文件的目录。这还需要相应虚拟主机节中的条目。</p>`,24)),a("p",null,[n(t,{href:"https://httpd.apache.org/docs/2.4/"},{default:i(()=>[...s[6]||(s[6]=[e("Apache 网站",-1)])]),_:1}),s[7]||(s[7]=e("描述了管理多个站点的其他方法，以及从性能调优到安全性的配置选项。",-1))]),s[26]||(s[26]=a("p",null,"Apache 是一个强大的 Web 服务器，可以用来管理从简单到高度复杂的网站。尽管其总体市场份额在缩小，但它仍然是互联网上最常用的 HTTPD 服务器。",-1)),s[27]||(s[27]=a("hr",null,null,-1)),a("p",null,[s[9]||(s[9]=e("via: ",-1)),n(t,{href:"https://opensource.com/article/18/3/configuring-multiple-web-sites-apache"},{default:i(()=>[...s[8]||(s[8]=[e("https://opensource.com/article/18/3/configuring-multiple-web-sites-apache",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("作者：",-1)),n(t,{href:"https://opensource.com/users/dboth"},{default:i(()=>[...s[10]||(s[10]=[e("David Both",-1)])]),_:1}),s[14]||(s[14]=e(" 译者：",-1)),n(t,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[11]||(s[11]=[e("MjSeven",-1)])]),_:1}),s[15]||(s[15]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:i(()=>[...s[17]||(s[17]=[e("Linux中国",-1)])]),_:1}),s[20]||(s[20]=e(" 荣誉推出",-1))])])}const y=p(h,[["render",c]]);export{v as __pageData,y as default};
